// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 funding, uint256 amount) public {
        // keep funding wide but well above dust; fund C via its payable fallback
        funding = bound(funding, 2 ether, 1000 ether);
        vm.deal(address(this), funding);
        (bool sent, ) = address(c).call{value: funding - 1}("");
        assertTrue(sent);

        uint256 balanceBefore = address(c).balance;
        // admissible domain: withdraw a strictly positive, proper part of the balance
        amount = bound(amount, 1, balanceBefore - 1);

        // the test contract is the owner (deployer); withdraw transfers to msg.sender
        c.withdraw(amount);

        // GENERAL RULE: withdrawing a proper part v < B leaves a positive remainder B - v.
        // The mutant drains the whole balance, leaving 0 whenever v < balanceBefore.
        assertTrue(address(c).balance == balanceBefore - amount && address(c).balance > 0);
    }

    receive() external payable {}
}
